import json

# Input data
jobs_data = [
    [(0, 3), (1, 2), (2, 2)],  
    [(0, 2), (2, 1), (1, 4)],  
    [(1, 4), (2, 3)]           
]

# Model definition
model = cp_model.CpModel()

# Decision Variables
job_starts = {}
job_ends = {}
for job_id, job in enumerate(jobs_data):
    for task_id, (machine_id, duration) in enumerate(job):
        job_starts[(job_id, task_id)] = model.NewIntVar(0, sum([d for _, d in j for j in jobs_data]), f'start_{job_id}_{task_id}')
        job_ends[(job_id, task_id)] = model.NewIntVar(0, sum([d for _, d in j for j in jobs_data]), f'end_{job_id}_{task_id}')

# Constraints
for job_id, job in enumerate(jobs_data):
    for task_id in range(len(job) - 1):
        model.Add(job_starts[(job_id, task_id + 1)] >= job_ends[(job_id, task_id)])

machine_starts = {}
machine_ends = {}
for job_id, job in enumerate(jobs_data):
    for task_id, (machine_id, duration) in enumerate(job):
        machine_starts.setdefault(machine_id, []).append(job_starts[(job_id, task_id)])
        machine_ends.setdefault(machine_id, []).append(job_ends[(job_id, task_id)])
        model.Add(job_ends[(job_id, task_id)] == job_starts[(job_id, task_id)] + duration)

for machine_id in machine_starts:
    intervals = []
    for i in range(len(machine_starts[machine_id])):
        start = machine_starts[machine_id][i]
        end = machine_ends[machine_id][i]
        intervals.append(model.NewIntervalVar(start, end - start, end, f'interval_{machine_id}_{i}'))
    model.AddNoOverlap(intervals)

# Objective function
makespan = model.NewIntVar(0, sum([d for _, d in j for j in jobs_data]), 'makespan')
model.AddMaxEquality(makespan, [job_ends[(job_id, len(job) - 1)] for job_id, job in enumerate(jobs_data)])
model.Minimize(makespan)

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {'makespan': solver.Value(makespan)}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
