    for w in range(n_weeks):
        model.Add(sum(assign[g, w, gr] for gr in range(n_groups)) == 1)

# Each group has the correct size
for w in range(n_weeks):
    for gr in range(n_groups):
        model.Add(sum(assign[g, w, gr] for g in range(n_golfers)) == group_size)

# No golfer plays with another golfer more than once
for g1 in range(n_golfers):
    for g2 in range(g1 + 1, n_golfers):
        model.Add(sum(assign[g1, w, gr] * assign[g2, w, gr] for w in range(n_weeks) for gr in range(n_groups)) <= 1)

